const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([157.706220, -34.344553]);
    const geometry = point.buffer(100 * 1000); // 100 km radius

    const dateRangeA_start = '2019-11-01';
    const dateRangeA_end = '2020-02-29'; // Includes leap day for Feb 2020
    const dateRangeB_start = '2018-11-01';
    const dateRangeB_end = '2019-02-28';

    const bandName = 'black_carbon_aod';

    // 2. Data Acquisition
    const collection = ee.ImageCollection('COPERNICUS/CAMS/GLO/AOD_550')
      .select(bandName);

    const collectionA = collection.filterDate(dateRangeA_start, dateRangeA_end)
      .filterBounds(geometry);
    const collectionB = collection.filterDate(dateRangeB_start, dateRangeB_end)
      .filterBounds(geometry);

    const sizeA = await collectionA.size().getInfo();
    const sizeB = await collectionB.size().getInfo();

    if (sizeA === 0 || sizeB === 0) {
      console.log(`2019-2020 Images: ${sizeA}, 2018-2019 Images: ${sizeB}`);
      console.log("C1: Empty Collection (No images found in date/location for one or both comparison points).");
      return;
    }
    console.log(`2019-2020 Images: ${sizeA}, 2018-2019 Images: ${sizeB}`);

    // Reduce collections to a single image (mean over time)
    const meanImageA = collectionA.mean();
    const meanImageB = collectionB.mean();

    // Set a consistent scale for reduction (CAMS resolution is ~0.5 degrees, ~50km)
    const scale = 5000; // 5 km scale to avoid too many pixels and still represent the area

    // 3. Processing and Calculation
    const reducer = ee.Reducer.mean();

    const statsA = await meanImageA.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const statsB = await meanImageB.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const valA = statsA ? statsA[bandName] : null;
    const countA = statsA ? statsA[bandName + '_count'] : 0;
    const valB = statsB ? statsB[bandName] : null;
    const countB = statsB ? statsB[bandName + '_count'] : 0;

    if (countA === 0 || countB === 0) {
      console.log(`2019-2020 Valid Pixels: ${countA}, 2018-2019 Valid Pixels: ${countB}`);
      console.log("C2: No Valid Pixels (Images exist, but after processing, 0 pixels remain).");
      return;
    }

    if (valA === null || isNaN(valA) || valB === null || isNaN(valB)) {
      console.log(`2019-2020 BC AOD: ${valA}, 2018-2019 BC AOD: ${valB}`);
      console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
      return;
    }

    // 5. Validation & Final Answer
    console.log(`2019-2020 Mean BC AOD: ${valA.toFixed(4)} (Pixels: ${countA})`);
    console.log(`2018-2019 Mean BC AOD: ${valB.toFixed(4)} (Pixels: ${countB})`);

    if (valA > valB) {
      console.log("A: Yes");
    } else {
      console.log("B: No");
    }

  } catch (error) {
    console.error("D: An error occurred during analysis:", error);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
